	public static Apfloat cdf(Apfloat x) {
		Apfloat ONE_HALF = NumberHelper.create("0.5", Main.RADIX, Main.NUMBER_PRECISION).real();
		Apfloat sqrtTwo = ApfloatMath.sqrt(MathUtils.TWO.real());

